package com.rx.admin.modules.system.user.mapper;  import org.apache.ibatis.annotations.*;  import java.util.List;  /**  * 鐢ㄦ埛鐩存帴鎺堟潈琛?Mapper  * 涓嶉€氳繃瑙掕壊锛岀洿鎺ュ皢鑿滃崟/鎸夐挳鏉冮檺鍏宠仈鍒扮敤鎴凤紝瀹炵幇涓€у寲鏉冮檺鎺у埗  */ @Mapper public interface SysUserMenuMapper {      @Insert("INSERT INTO sys_user_menu (user_id, menu_id) VALUES (#{userId}, #{menuId})")     int insert(@Param("userId") Long userId, @Param("menuId") Long menuId);      @Delete("DELETE FROM sys_user_menu WHERE user_id = #{userId} AND menu_id = #{menuId}")     int deleteByUserIdAndMenuId(@Param("userId") Long userId, @Param("menuId") Long menuId);      @Delete("DELETE FROM sys_user_menu WHERE user_id = #{userId}")     int deleteByUserId(@Param("userId") Long userId);      @Select("SELECT menu_id FROM sys_user_menu WHERE user_id = #{userId}")     List<Long> selectMenuIdsByUserId(@Param("userId") Long userId);      /**      * 鏌ヨ鐢ㄦ埛鐩存帴鎺堟潈鐨勬潈闄愭爣璇嗭紙perms锛?     */     @Select("SELECT DISTINCT m.perms FROM sys_user_menu um " +             "JOIN sys_menu m ON um.menu_id = m.id " +             "WHERE um.user_id = #{userId} AND m.perms IS NOT NULL AND m.perms != '' " +             "AND m.status = 1 AND m.deleted = 0")     List<String> selectPermsByUserId(@Param("userId") Long userId);      /**      * 鏌ヨ鐢ㄦ埛鐩存帴鎺堟潈鐨勮彍鍗曪紙鍚鍏堣妭鐐癸紝鐢ㄤ簬鏋勫缓鑿滃崟鏍戯級      */     @Select("<script>" +             "WITH RECURSIVE menu_tree AS (" +             "  SELECT m.* FROM sys_menu m " +             "  JOIN sys_user_menu um ON m.id = um.menu_id " +             "  WHERE um.user_id = #{userId} AND m.status = 1 AND m.deleted = 0 " +             "  UNION " +             "  SELECT p.* FROM sys_menu p " +             "  JOIN menu_tree mt ON p.id = mt.parent_id " +             "  WHERE p.status = 1 AND p.deleted = 0" +             ") SELECT DISTINCT * FROM menu_tree ORDER BY sort ASC" +             "</script>")     List<com.rx.admin.modules.system.menu.entity.SysMenu> selectMenusByUserId(@Param("userId") Long userId); }